    ke(11,1) = lr1;    // theta_z2-v1
    // theta_z2-theta_z1: SK3
    ke(11,5) = sk3;    // theta_z2-theta_z1
    // theta_z2-v2: -LR1
    ke(11,7) = -lr1;   // theta_z2-v2
    ke(11,11) = sk1;   // theta_z2-theta_z2

